  e->rec=rec;
  e->bodylines=body;
  rec+=1UL+body;
 }
 if(rec-1UL!=expected) {
  puts("M205 STAGE RECORD COUNT MISMATCH");
  return 0;
 }
 for(k=0;k<count;k++) {
  start=((unsigned long)k*total)/(unsigned long)count+1UL;
  end=((unsigned long)(k+1)*total)/(unsigned long)count;
  picked[k]=0;
  for(n=start;n<=end;n++) {
   e=bynum+n;
   if(e->size==0UL||e->size>2048UL||
      e->bodylines==0UL||e->bodylines>limit) continue;
   picked[k]=n;
   break;
  }
  if(!picked[k]) {
   puts("M205 NO ELIGIBLE OBJECT IN BAND");
   return 0;
  }
 }
 for(k=0;k<count;k++) {
  n=picked[k];
  e=bynum+n;
  printf("P201 %lu %lu %lu %d %lu ",
         n,e->rec,e->bodylines,e->type,e->size);
  oidprint(e->oid);
  putchar('\n');
 }
 return 1;
}

