    !numeric(argv[3],&limit)||
    !numeric(argv[4],&num)||
    expected==0||expected>MAXREC||
    limit==0||limit>64UL||
    num<2UL||num>8UL) {
  puts("Usage: GITP25M SAMPLE records max-body 2..8");
  return 4;
 }
 if(!indexread()) goto done;
 if(sample(expected,limit,(int)num)) rc=0;
done:
 free(bynum);
 return rc;
}

